// Faixa típica: 50-85°C, oscilando em torno de uma baseline com tendência lenta
let state = context.get('state') || { baseline: 68, trend: 0 };

// Tendência lenta (passeio aleatório suave)
state.trend += (Math.random() - 0.5) * 0.1;
state.trend = Math.max(-3, Math.min(3, state.trend));
state.baseline = 68 + state.trend;

// Ruído sobre a baseline
const noise = (Math.random() - 0.5) * 2.5;
const value = +(state.baseline + noise).toFixed(2);

context.set('state', state);

msg.topic = "plant/01/area/BRITAGEM/equipment/JAW-CRUSHER-01/sensor/temperature_bearing";
msg.payload = {
    timestamp: new Date().toISOString(),
    plant_id: "01",
    area_id: "BRITAGEM",
    equipment_id: "JAW-CRUSHER-01",
    equipment_type: "jaw_crusher",
    sensor_id: "temperature_bearing",
    value: value,
    unit: "celsius",
    quality: value > 80 ? "warning" : "good"
};

return msg;

// Faixa típica: 120-180 bar
let state = context.get('state') || { baseline: 150 };

state.baseline += (Math.random() - 0.5) * 1.5;
state.baseline = Math.max(125, Math.min(175, state.baseline));

const noise = (Math.random() - 0.5) * 3;
const value = +(state.baseline + noise).toFixed(1);

context.set('state', state);

msg.topic = "plant/01/area/BRITAGEM/equipment/JAW-CRUSHER-01/sensor/pressure_hydraulic";
msg.payload = {
