    equipment_id: "JAW-CRUSHER-01",
    equipment_type: "jaw_crusher",
    sensor_id: "pressure_hydraulic",
    value: value,
    unit: "bar",
    quality: "good"
};

return msg;

// Faixa típica: 2-8 mm/s; ocasionalmente picos curtos
let state = context.get('state') || { baseline: 4.2 };

// Tendência lenta
state.baseline += (Math.random() - 0.5) * 0.15;
state.baseline = Math.max(3, Math.min(6.5, state.baseline));

// Ruído rápido e ocasionalmente um pico
let noise = (Math.random() - 0.5) * 1.2;
if (Math.random() < 0.03) {
    noise += Math.random() * 2.5; // pico ocasional
}
const value = +(state.baseline + noise).toFixed(2);

context.set('state', state);

msg.topic = "plant/01/area/BRITAGEM/equipment/JAW-CRUSHER-01/sensor/vibration";
msg.payload = {
    timestamp: new Date().toISOString(),
    plant_id: "01",
    area_id: "BRITAGEM",
    equipment_id: "JAW-CRUSHER-01",
    equipment_type: "jaw_crusher",
    sensor_id: "vibration",
    value: value,
    unit: "mm/s",
    quality: value > 7 ? "warning" : "good"
};

return msg;

